namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        for (var i = 0; i < 5; i++)
        {
            _notifications.Add(new Notification(
                _nextId++,
                $"Welcome notification #{i + 1}",
                DateTime.UtcNow.AddMinutes(-10 + i)));
        }
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>Simulates a new notification arriving at random intervals.</summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            _notifications.Add(new Notification(
                _nextId,
                $"New event at {DateTime.UtcNow:T} (#{_nextId})",
                DateTime.UtcNow));
            _nextId++;
        }
    }
}

@page "/notifications"
@using NotificationsApp.Services
@implements IDisposable
@inject NotificationService Svc
@rendermode @(new InteractiveServerRenderMode(prerender: true))

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>#@n.Id</strong> &mdash; @n.Message
                <small class="text-muted ms-2">@n.Timestamp.ToString("T")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    // Runs during both prerender AND interactive init.
    // On prerender it populates the initial HTML.
    // On interactive init, the framework replays the same component state,
    // so we reload from the service to keep the list current.
    protected override void OnInitialized()
    {
        _notifications = Svc.GetAll();
        _lastSeenId = _notifications.Count > 0
            ? _notifications.Max(n => n.Id)
            : 0;
    }

    // Only called once the circuit is live (not during static SSR prerender).
    // This is the safe place to start the polling loop.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Simulate the server generating traffic.
            Svc.SimulateIncoming();

            var newer = Svc.GetSince(_lastSeenId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

